"""Conservative cleanup of files generated by one framework run."""

from __future__ import annotations

import logging  # noqa: TID251 - standalone wrapper uses stdlib logging
from dataclasses import dataclass, field
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from pathlib import Path

log = logging.getLogger(__name__)


@dataclass
class Manifest:
    """Tracks newly-created files; pre-existing paths are never registered."""

    paths: list[Path] = field(default_factory=list)

    def add(self, path: Path) -> Path:
        path = path.resolve()
        if path not in self.paths:
            self.paths.append(path)
        return path

    def cleanup(self) -> list[Path]:
        removed: list[Path] = []
        for path in reversed(self.paths):
            try:
                if path.is_file() or path.is_symlink():
                    path.unlink()
                    removed.append(path)
            except OSError as exc:
                log.warning("could not remove generated file %s: %s", path, exc)
        return removed
